CREATE OR REPLACE FUNCTION tag_links_counters_insert() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
        UPDATE tags SET usage_count = usage_count + 1 WHERE tag_id = NEW.tag_id;
        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS tag_links_counters_insert ON tag_links
-- ==stmt==
CREATE TRIGGER tag_links_counters_insert AFTER INSERT ON tag_links
            FOR EACH ROW EXECUTE FUNCTION tag_links_counters_insert()
-- ==stmt==
CREATE OR REPLACE FUNCTION tag_links_counters_delete() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
        UPDATE tags SET usage_count = GREATEST(0, usage_count - 1) WHERE tag_id = OLD.tag_id;
        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS tag_links_counters_delete ON tag_links
-- ==stmt==
CREATE TRIGGER tag_links_counters_delete AFTER DELETE ON tag_links
            FOR EACH ROW EXECUTE FUNCTION tag_links_counters_delete()
-- ==stmt==
CREATE OR REPLACE FUNCTION favorites_counters_insert() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN

        UPDATE images SET favorites = favorites + 1 WHERE image_id = NEW.image_id;
        UPDATE users SET favorites = favorites + 1 WHERE user_id = NEW.user_id;

        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS favorites_counters_insert ON favorites
-- ==stmt==
CREATE TRIGGER favorites_counters_insert AFTER INSERT ON favorites
            FOR EACH ROW EXECUTE FUNCTION favorites_counters_insert()
-- ==stmt==
CREATE OR REPLACE FUNCTION favorites_counters_delete() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN

        UPDATE images SET favorites = favorites - 1 WHERE image_id = OLD.image_id;
        UPDATE users SET favorites = favorites - 1 WHERE user_id = OLD.user_id;

        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS favorites_counters_delete ON favorites
-- ==stmt==
CREATE TRIGGER favorites_counters_delete AFTER DELETE ON favorites
            FOR EACH ROW EXECUTE FUNCTION favorites_counters_delete()
-- ==stmt==
CREATE OR REPLACE FUNCTION favorites_counters_update() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN

        IF OLD.image_id IS DISTINCT FROM NEW.image_id THEN
            UPDATE images SET favorites = favorites - 1 WHERE image_id = OLD.image_id;
            UPDATE images SET favorites = favorites + 1 WHERE image_id = NEW.image_id;
        END IF;
        IF OLD.user_id IS DISTINCT FROM NEW.user_id THEN
            UPDATE users SET favorites = favorites - 1 WHERE user_id = OLD.user_id;
            UPDATE users SET favorites = favorites + 1 WHERE user_id = NEW.user_id;
        END IF;

        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS favorites_counters_update ON favorites
-- ==stmt==
CREATE TRIGGER favorites_counters_update AFTER UPDATE ON favorites
            FOR EACH ROW EXECUTE FUNCTION favorites_counters_update()
-- ==stmt==
CREATE OR REPLACE FUNCTION images_counters_insert() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
        UPDATE users SET image_posts = image_posts + 1 WHERE user_id = NEW.user_id;
        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS images_counters_insert ON images
-- ==stmt==
CREATE TRIGGER images_counters_insert AFTER INSERT ON images
            FOR EACH ROW EXECUTE FUNCTION images_counters_insert()
-- ==stmt==
CREATE OR REPLACE FUNCTION images_counters_delete() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
