        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS images_counters_delete ON images
-- ==stmt==
CREATE TRIGGER images_counters_delete AFTER DELETE ON images
            FOR EACH ROW EXECUTE FUNCTION images_counters_delete()
-- ==stmt==
CREATE OR REPLACE FUNCTION images_counters_update() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN

        IF OLD.user_id IS DISTINCT FROM NEW.user_id THEN
            UPDATE users SET image_posts = image_posts - 1 WHERE user_id = OLD.user_id;
            UPDATE users SET image_posts = image_posts + 1 WHERE user_id = NEW.user_id;
        END IF;

        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS images_counters_update ON images
-- ==stmt==
CREATE TRIGGER images_counters_update AFTER UPDATE ON images
            FOR EACH ROW EXECUTE FUNCTION images_counters_update()
-- ==stmt==
CREATE OR REPLACE FUNCTION posts_counters_insert() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN

        IF NOT NEW.deleted THEN
            UPDATE images SET posts = posts + 1, last_post = NEW.date
                WHERE image_id = NEW.image_id;
            UPDATE users SET posts = posts + 1 WHERE user_id = NEW.user_id;
        END IF;

        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS posts_counters_insert ON posts
-- ==stmt==
CREATE TRIGGER posts_counters_insert AFTER INSERT ON posts
            FOR EACH ROW EXECUTE FUNCTION posts_counters_insert()
-- ==stmt==
CREATE OR REPLACE FUNCTION posts_counters_update() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN

        IF OLD.deleted = false AND NEW.deleted = true THEN
            UPDATE images
            SET posts = posts - 1,
                last_post = (SELECT MAX(date) FROM posts
                             WHERE image_id = NEW.image_id AND NOT deleted)
            WHERE image_id = NEW.image_id;
            UPDATE users SET posts = posts - 1 WHERE user_id = NEW.user_id;
        ELSIF OLD.deleted = true AND NEW.deleted = false THEN
            UPDATE images
            SET posts = posts + 1,
                last_post = (SELECT MAX(date) FROM posts
                             WHERE image_id = NEW.image_id AND NOT deleted)
            WHERE image_id = NEW.image_id;
            UPDATE users SET posts = posts + 1 WHERE user_id = NEW.user_id;
        ELSE
            IF OLD.image_id IS DISTINCT FROM NEW.image_id THEN
                UPDATE images
                SET posts = posts - 1,
                    last_post = (SELECT MAX(date) FROM posts
                                 WHERE image_id = OLD.image_id AND NOT deleted)
                WHERE image_id = OLD.image_id;
                UPDATE images
                SET posts = posts + 1,
                    last_post = (SELECT MAX(date) FROM posts
                                 WHERE image_id = NEW.image_id AND NOT deleted)
                WHERE image_id = NEW.image_id;
            END IF;
            IF OLD.user_id IS DISTINCT FROM NEW.user_id THEN
                UPDATE users SET posts = posts - 1 WHERE user_id = OLD.user_id;
                UPDATE users SET posts = posts + 1 WHERE user_id = NEW.user_id;
            END IF;
        END IF;

        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS posts_counters_update ON posts
-- ==stmt==
CREATE TRIGGER posts_counters_update AFTER UPDATE ON posts
            FOR EACH ROW EXECUTE FUNCTION posts_counters_update()
-- ==stmt==
CREATE OR REPLACE FUNCTION posts_counters_delete() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN

        IF NOT OLD.deleted THEN
            UPDATE images
            SET posts = posts - 1,
                last_post = (SELECT MAX(date) FROM posts
                             WHERE image_id = OLD.image_id AND NOT deleted)
            WHERE image_id = OLD.image_id;
            UPDATE users SET posts = posts - 1 WHERE user_id = OLD.user_id;
        END IF;

        RETURN NULL;
        END $$
-- ==stmt==
DROP TRIGGER IF EXISTS posts_counters_delete ON posts
-- ==stmt==
CREATE TRIGGER posts_counters_delete AFTER DELETE ON posts
            FOR EACH ROW EXECUTE FUNCTION posts_counters_delete()
